mapper.select:
select nvl(pcrp.DEFAULT_VALUE, 0) from prj_credit_reply_para pcrp where pcrp.REPLY_ID = #{replyId}
and pcrp.REPLY_PARA = 'FINANCE_AMOUNT_MAX'
and pcrp.REPLY_PARA = 'FINANCE_AMOUNT_MAX_NP'

select p.*
from prj_project pp,
    prj_credit_reply_para p
where pp.project_id = #{projectId}
and p.reply_id = pp.project_id
and r.LATEST_FLAG = 'Y'
and r.REPLY_ID = p.REPLY_ID
and p.REPLY_PARA = #{replyPara}
